package com.luci.pianoroom;
import java.io.*;import java.util.Base64;
/** Stable file-based bank references; Android MIDI device IDs are never persisted. */
public final class Scene {
 public final ChannelSettings[] effects={new ChannelSettings(),new ChannelSettings(),new ChannelSettings(),new ChannelSettings()};public boolean xyEnabled;public int xyA,xyB=1,xyMode;public float xyX=.5f,xyY;
 public String name="Minha cena";public final String[] banks={"GeneralUser-GS.sf2","GeneralUser-GS.sf2","GeneralUser-GS.sf2","GeneralUser-GS.sf2"};public final int[] programs=new int[4];public final float[] gains={.8f,0,0,0};public final boolean[] muted=new boolean[4];public int solo=-1,pianoMode=1;public float master=.8f,wet=.25f;public int room=1,transpose,voices=256,pianoVolume=127,pianoReverb=40;public boolean yamaha;
 public String encode()throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(DataOutputStream out=new DataOutputStream(bytes)){out.writeInt(6);out.writeUTF(name);for(int i=0;i<4;i++){out.writeUTF(banks[i]);out.writeInt(programs[i]);out.writeFloat(gains[i]);}out.writeFloat(master);out.writeFloat(wet);out.writeInt(room);out.writeInt(transpose);out.writeInt(voices);out.writeBoolean(yamaha);out.writeInt(pianoVolume);out.writeInt(pianoReverb);for(boolean mute:muted)out.writeBoolean(mute);out.writeInt(solo);out.writeInt(pianoMode);for(ChannelSettings c:effects)c.write(out);out.writeBoolean(xyEnabled);out.writeInt(xyA);out.writeInt(xyB);out.writeInt(xyMode);out.writeFloat(xyX);out.writeFloat(xyY);for(ChannelSettings c:effects)c.writePiano(out);for(ChannelSettings c:effects)c.writeBody(out);for(ChannelSettings c:effects)c.writeSpace(out);}return Base64.getEncoder().encodeToString(bytes.toByteArray());}
 public static Scene decode(String value)throws IOException{try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(value)))){int version=in.readInt();if(version!=1&&version!=2&&version!=3&&version!=4&&version!=5&&version!=6)throw new IOException("Versão de cena incompatível");Scene s=new Scene();s.name=in.readUTF();if(s.name.length()>100)throw new IOException("Nome de cena excessivo");for(int i=0;i<4;i++){s.banks[i]=in.readUTF();if(s.banks[i].contains("/")||s.banks[i].contains("\\")||s.banks[i].length()>200)throw new IOException("Referência de banco inválida");s.programs[i]=in.readInt();s.gains[i]=in.readFloat();if(s.programs[i]<0||s.programs[i]>65535||!finite(s.gains[i],0,2))throw new IOException("Canal inválido");}s.master=in.readFloat();s.wet=in.readFloat();s.room=in.readInt();s.transpose=in.readInt();s.voices=in.readInt();s.yamaha=in.readBoolean();s.pianoVolume=in.readInt();s.pianoReverb=in.readInt();if(version>=2){for(int i=0;i<4;i++)s.muted[i]=in.readBoolean();s.solo=in.readInt();s.pianoMode=in.readInt();}if(version>=3){for(int i=0;i<4;i++)s.effects[i]=ChannelSettings.read(in);s.xyEnabled=in.readBoolean();s.xyA=in.readInt();s.xyB=in.readInt();s.xyMode=in.readInt();s.xyX=in.readFloat();s.xyY=in.readFloat();if(s.xyA<0||s.xyA>3||s.xyB<0||s.xyB>3||s.xyMode<0||s.xyMode>2||s.xyEnabled&&s.xyA==s.xyB||!finite(s.xyX,0,1)||!finite(s.xyY,0,1))throw new IOException("Controle XY inválido");}if(version>=4)for(ChannelSettings c:s.effects)c.readPiano(in);if(version>=5)for(ChannelSettings c:s.effects)c.readBody(in);if(version>=6)for(ChannelSettings c:s.effects)c.readSpace(in);if(!finite(s.master,0,2)||!finite(s.wet,0,1)||s.room<0||s.room>3||s.transpose< -12||s.transpose>12||(s.voices!=256&&s.voices!=512&&s.voices!=768)||s.pianoVolume<0||s.pianoVolume>127||s.pianoReverb<0||s.pianoReverb>127||s.solo< -1||s.solo>4||s.pianoMode<0||s.pianoMode>2||in.available()!=0)throw new IOException("Ajustes da cena inválidos");return s;}catch(IllegalArgumentException e){throw new IOException("Cena inválida",e);}}
 private static boolean finite(float v,float min,float max){return !Float.isNaN(v)&&!Float.isInfinite(v)&&v>=min&&v<=max;}
}
